    ) -> Result<Self, GrowthFailure<E>> {
        pay(size_of::<Self>()).map_err(GrowthFailure::Payment)?;
        Ok(Self {
            bytes: String::new(),
            logical: active(),
        })
    }

    fn append<E>(
        &mut self,
        value: &str,
        pay: &mut impl FnMut(usize) -> Result<(), E>,
        logical: bool,
        strict: bool,
